import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  const CORE_COUNT = 90;
  const FIELD_COUNT = 1110;
  const PARTICLE_RADIUS = 0.012;

  // Icosahedron base geometry
  const baseGeom = new THREE.IcosahedronGeometry(PARTICLE_RADIUS, 2);

  // Field material: paper color, non-metallic, self-lit
  const fieldMaterial = new THREE.MeshStandardMaterial({
    color: 0xe8ecf2,
    metalness: 0,
    roughness: 1,
    emissive: 0xe8ecf2,
    emissiveIntensity: 0.9,
    fog: true,
    transparent: true,
  });

  // Core material: accent red, additive glow
  const coreMaterial = new THREE.MeshStandardMaterial({
    color: 0xff2a38,
    metalness: 0.5,
    roughness: 0.8,
    emissive: 0xff2a38,
    emissiveIntensity: 1.8,
    fog: false,
    transparent: true,
    blending: THREE.AdditiveBlending,
  });

  // Generate field particle positions (ellipsoidal shell)
  const fieldPositions = [];
  const ellipsoid = new THREE.Vector3(3, 2, 2.5);
  const shellCenter = new THREE.Vector3(0, 0, -1.5);

  for (let i = 0; i < FIELD_COUNT; i++) {
    const phi = Math.random() * Math.PI * 2;
    const theta = Math.acos(Math.random() * 2 - 1);
    const shellRadius = 0.8 + Math.random() * 0.2;

    const pos = new THREE.Vector3(
      ellipsoid.x * shellRadius * Math.sin(theta) * Math.cos(phi),
      ellipsoid.y * shellRadius * Math.sin(theta) * Math.sin(phi),
      ellipsoid.z * shellRadius * Math.cos(theta)
    ).add(shellCenter);

    fieldPositions.push(pos);
  }

  // Create field mesh
  const fieldMesh = new THREE.InstancedMesh(baseGeom, fieldMaterial, FIELD_COUNT);
  fieldPositions.forEach((pos, i) => {
    const m = new THREE.Matrix4().setPosition(pos);
    fieldMesh.setMatrixAt(i, m);
  });
  fieldMesh.instanceMatrix.needsUpdate = true;

  // Generate core particle positions (sphere at origin)
  const corePositions = [];
  const coreRadius = 0.5;

  for (let i = 0; i < CORE_COUNT; i++) {
    const phi = Math.random() * Math.PI * 2;
    const theta = Math.acos(Math.random() * 2 - 1);
    const r = Math.random() * coreRadius;

    const pos = new THREE.Vector3(
      r * Math.sin(theta) * Math.cos(phi),
      r * Math.sin(theta) * Math.sin(phi),
      r * Math.cos(theta)
    );

    corePositions.push(pos);
  }

  // Create core mesh
  const coreMesh = new THREE.InstancedMesh(baseGeom, coreMaterial, CORE_COUNT);
  corePositions.forEach((pos, i) => {
    const m = new THREE.Matrix4().setPosition(pos);
    coreMesh.setMatrixAt(i, m);
  });
  coreMesh.instanceMatrix.needsUpdate = true;

  group.add(fieldMesh);
  group.add(coreMesh);

  // Fog for depth effect
  group.userData.fog = new THREE.Fog(0x0b0b10, 4, 10);

  // Text rendering via fontAtlas (MSDF)
  if (ctx.fontAtlas) {
    // Hero: "NOVA ATELIER"
    const heroText = ctx.fontAtlas.createTextMesh({
      text: 'NOVA ATELIER',
      fontFamily: 'Lora',
      fontSize: 124,
      fontWeight: 600,
      letterSpacing: -0.01,
      lineHeight: 1.02,
      color: 0xe8ecf2,
      atlasIndex: 0,
    });
    if (heroText) {
      heroText.position.set(0, 0.5, 0.5);
      group.add(heroText);
    }

    // Subhead: positioned 0.75 units below hero baseline
    const subheadText = ctx.fontAtlas.createTextMesh({
      text: 'Precision instruments for the dark hours.',
      fontFamily: 'JetBrains Mono',
      fontSize: 40,
      fontWeight: 400,
      letterSpacing: 0.02,
      lineHeight: 1.35,
      color: 0xe8ecf2,
      atlasIndex: 0,
    });
    if (subheadText) {
      subheadText.position.set(0, 0.5 - 0.75, 0.5);
      group.add(subheadText);
    }

    // Caption: pinned 2.25 units below center
    const captionText = ctx.fontAtlas.createTextMesh({
      text: 'EST. 2019 / GENEVA AND KYOTO',
      fontFamily: 'JetBrains Mono',
      fontSize: 18,
      fontWeight: 400,
      letterSpacing: 0.08,
      lineHeight: 1.4,
      color: 0xe8ecf2,
      atlasIndex: 0,
    });
    if (captionText) {
      captionText.position.set(0, -2.25, 0.5);
      group.add(captionText);
    }
  }

  // Apply particle-emerge cinematic primitive
  if (ctx.primitives && config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      if (prim.name === 'particle-emerge' && ctx.primitives[prim.name]) {
        ctx.primitives[prim.name](group, prim.params || {});
      }
    });
  }

  // Animation state
  let rafId = null;
  const startTime = Date.now();

  const animate = () => {
    const elapsed = (Date.now() - startTime) / 1000;

    // Ambient drift: each particle orbits anchor by ±0.04 at 0.05 Hz
    fieldPositions.forEach((anchor, i) => {
      const phase = i * 0.1;
      const orbitSpeed = 0.05;
      const angle = 2 * Math.PI * orbitSpeed * elapsed + phase;
      const orbitRadius = 0.04;

      const m = new THREE.Matrix4().setPosition(
        anchor.x + orbitRadius * Math.cos(angle),
        anchor.y + orbitRadius * Math.sin(angle),
        anchor.z
      );
      fieldMesh.setMatrixAt(i, m);
    });
    fieldMesh.instanceMatrix.needsUpdate = true;

    corePositions.forEach((anchor, i) => {
      const phase = i * 0.1;
      const orbitSpeed = 0.05;
      const angle = 2 * Math.PI * orbitSpeed * elapsed + phase;
      const orbitRadius = 0.04;

      const m = new THREE.Matrix4().setPosition(
        anchor.x + orbitRadius * Math.cos(angle),
        anchor.y + orbitRadius * Math.sin(angle),
        anchor.z
      );
      coreMesh.setMatrixAt(i, m);
    });
    coreMesh.instanceMatrix.needsUpdate = true;

    // Core pulse: emissive 1.5 → 1.8 sine at 0.1 Hz
    const pulseValue = 1.5 + 0.3 * Math.sin(2 * Math.PI * 0.1 * elapsed);
    coreMaterial.emissiveIntensity = pulseValue;

    rafId = requestAnimationFrame(animate);
  };

  rafId = requestAnimationFrame(animate);

  // Cleanup
  group.userData.cleanup = () => {
    if (rafId) cancelAnimationFrame(rafId);
    baseGeom.dispose();
    fieldMaterial.dispose();
    coreMaterial.dispose();
    fieldMesh.dispose();
    coreMesh.dispose();
  };

  group.userData.handlers = {};

  return group;
}
